import { useRef, useMemo, useState, useCallback } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useVirtualizer } from "@tanstack/react-virtual";
import { supabase } from "@/integrations/supabase/client";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Radio, Calendar, Search, RefreshCw, Bell, ExternalLink, Filter, X, Bookmark, BookmarkCheck } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { AISummaryDialog } from "@/components/AISummaryDialog";
import { useWatchlist } from "@/lib/watchlist";
import { useRealtimeFeed } from "@/hooks/useRealtimeFeed";
import type { ThreatItem } from "@/hooks/useRealtimeFeed";

function timeAgo(iso: string) {
  const diff = Date.now() - new Date(iso).getTime();
  const m = Math.floor(diff / 60000);
  if (m < 1) return "just now";
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.floor(h / 24)}d ago`;
}

const SEV_COLOR: Record<string, string> = {
  critical: "border-l-red-500 bg-red-500/5",
  high:     "border-l-orange-400 bg-orange-400/5",
  medium:   "border-l-blue-400 bg-blue-400/5",
  low:      "border-l-green-500 bg-green-500/5",
};

const SEV_BADGE: Record<string, string> = {
  critical: "bg-red-500/15 text-red-400 border-red-500/40",
  high:     "bg-orange-400/15 text-orange-400 border-orange-400/40",
  medium:   "bg-blue-400/15 text-blue-400 border-blue-400/40",
  low:      "bg-green-500/15 text-green-400 border-green-500/40",
};

import { applyHiddenSourceFilter, filterFeedItems, sortByPriorityThenRecency, itemRecencyDate } from "@/lib/feed-filters";
import { useBackgroundRefreshListener } from "@/hooks/useBackgroundRefreshListener";

const FEED_QUERY_KEY = ["threat_items", "feed"] as const;

// Curated live feed — hides NVD/GitHub/IOC dumps; newest ingested items first.
async function fetchFeedItems(): Promise<ThreatItem[]> {
  // Pull a much wider window so analysts get worldwide live coverage rather
  // than just the last few hundred items. Use fetched_at (always set) as the
  // ordering key — published_at can be NULL for some upstream feeds and
  // those rows get silently dropped when ordering by it.
  let { data, error } = await applyHiddenSourceFilter(
    supabase.from("threat_items").select(
      "id,title,link,severity,source_name,source_url,category,published_at,fetched_at," +
      "excerpt,ai_summary,ai_model,ai_summary_at,iocs,confidence_score,severity_reasons," +
      "mitre_techniques,threat_actors,malware_families,cross_source_count"
    )
  )
    .order("fetched_at", { ascending: false, nullsFirst: false })
    .limit(2000);

  // Graceful fallback if newer columns don't exist
  if (error?.message?.includes("column") || error?.message?.includes("does not exist")) {
    const fb = await applyHiddenSourceFilter(
      supabase.from("threat_items").select(
        "id,title,link,severity,source_name,category,published_at,fetched_at,excerpt,ai_summary"
      )
    )
      .order("fetched_at", { ascending: false, nullsFirst: false })
      .limit(2000);
    data = fb.data as any;
    error = fb.error;
  }

  if (error) throw error;

  const items = filterFeedItems((data ?? []) as ThreatItem[]);
  return sortByPriorityThenRecency(items);
}

export default function Feed() {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const wl = useWatchlist();

  const [watchedIds, setWatchedIds]   = useState<Set<string>>(new Set());
  const [newCount, setNewCount]       = useState(0);
  const [search, setSearch]           = useState("");
  const [sevFilter, setSevFilter]     = useState("all");
  const [catFilter, setCatFilter]     = useState("all");
  const parentRef                     = useRef<HTMLDivElement>(null);

  // ── TanStack Query: initial load + silent background updates (no page reload) ──
  const { data: items = [], isLoading, isFetching, refetch } = useQuery({
    queryKey: FEED_QUERY_KEY,
    queryFn: fetchFeedItems,
    staleTime: 5_000,
    gcTime: 5 * 60_000,
    refetchInterval: false,
    placeholderData: (prev) => prev,
  });

  useBackgroundRefreshListener(() => { refetch(); });

  // ── Realtime: push new items into query cache ────────────────────────────────
  useRealtimeFeed({
    enabled: true,
    onNewItem: useCallback(() => {
      setNewCount(n => n + 1);
    }, []),
  });

  const acceptNewItems = () => setNewCount(0);

  const refreshFeed = async () => {
    setNewCount(0);
    await refetch();
    toast({ title: "Feed refreshed" });
  };

  const toggleWatch = async (item: ThreatItem) => {
    const watched = watchedIds.has(item.id);
    if (watched) {
      await wl.remove(item.id);
      setWatchedIds(prev => { const n = new Set(prev); n.delete(item.id); return n; });
    } else {
      await wl.add({
        id: item.id, title: item.title, link: item.link,
        severity: item.severity, source_name: item.source_name ?? "",
        category: item.category ?? "", published_at: item.published_at,
        ai_summary: item.ai_summary ?? null,
      });
      setWatchedIds(prev => new Set([...prev, item.id]));
    }
  };

  // ── Derived data ─────────────────────────────────────────────────────────────
  const categories = useMemo(() => {
    const cats = new Set(items.map(i => i.category).filter(Boolean));
    return ["all", ...Array.from(cats).sort()];
  }, [items]);

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    return items.filter(item => {
      // Feed Articles = full firehose; no source-blocklist here. (Sources
      // remain hidden from the main dashboard, just not from this page.)
      if (sevFilter !== "all" && item.severity !== sevFilter) return false;
      if (catFilter !== "all" && item.category !== catFilter) return false;
      if (q) {
        const hay = `${item.title} ${item.source_name ?? ""} ${item.excerpt ?? ""} ${item.category ?? ""}`.toLowerCase();
        if (!hay.includes(q)) return false;
      }
      return true;
    });
  }, [items, search, sevFilter, catFilter]);

  const stats = useMemo(() => ({
    critical: items.filter(i => i.severity === "critical").length,
    high:     items.filter(i => i.severity === "high").length,
    total:    items.length,
  }), [items]);

  // ── Virtual scrolling ────────────────────────────────────────────────────────
  const rowVirtualizer = useVirtualizer({
    count:           filtered.length,
    getScrollElement: () => parentRef.current,
    estimateSize:    () => 52,     // estimated card height px
    overscan:        12,           // pre-render 12 items above/below viewport
  });

  return (
    <div className="container mx-auto px-4 py-8">
      {/* ── Header ──────────────────────────────────────────────────────────── */}
      <div className="mb-6">
        <div className="flex items-center gap-3 mb-2 flex-wrap">
          <Radio className="h-6 w-6 text-green-500 animate-pulse" />
          <h1 className="text-3xl font-bold tracking-tight">Live Threat Feed</h1>
          <Badge variant="outline" className="border-green-500/40 text-green-400 text-[10px] gap-1">
            <span className="h-1.5 w-1.5 rounded-full bg-green-500 animate-pulse" />
            LIVE · Realtime
          </Badge>
          <div className="ml-auto flex items-center gap-2">
            <span className="text-xs text-muted-foreground">
              <span className="text-red-400 font-bold">{stats.critical}</span> critical ·{" "}
              <span className="text-orange-400 font-bold">{stats.high}</span> high ·{" "}
              {stats.total} total
            </span>
            <Button
              size="sm"
              variant="outline"
              onClick={refreshFeed}
              disabled={isFetching}
              className="gap-1.5 text-xs h-8"
            >
              <RefreshCw className={`h-3.5 w-3.5 ${isFetching ? "animate-spin" : ""}`} /> Refresh
            </Button>
          </div>
        </div>
        <p className="text-muted-foreground text-sm">
          Curated live cyber threat stream · NVD/IOC dumps hidden · Supabase Realtime push updates
        </p>
      </div>

      {/* ── New items banner ─────────────────────────────────────────────────── */}
      {newCount > 0 && (
        <button
          onClick={acceptNewItems}
          className="w-full mb-4 flex items-center justify-center gap-2 rounded-lg border border-green-500/40 bg-green-500/10 py-2.5 text-sm text-green-400 hover:bg-green-500/15 transition-colors animate-pulse"
        >
          <Bell className="h-4 w-4" />
          {newCount} new intel item{newCount > 1 ? "s" : ""} received — click to acknowledge
        </button>
      )}

      {/* ── Filters ─────────────────────────────────────────────────────────── */}
      <div className="flex flex-wrap gap-2 mb-4">
        <div className="relative flex-1 min-w-48">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search title, source, category…"
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="pl-9 h-8 text-sm"
          />
          {search && (
            <button onClick={() => setSearch("")} className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground">
              <X className="h-3.5 w-3.5" />
            </button>
          )}
        </div>

        <div className="flex gap-1">
          {["all", "critical", "high", "medium", "low"].map(s => (
            <Button
              key={s}
              size="sm"
              variant={sevFilter === s ? "default" : "outline"}
              onClick={() => setSevFilter(s)}
              className="h-8 text-xs capitalize"
            >
              {s}
            </Button>
          ))}
        </div>

        {categories.length > 2 && (
          <div className="flex items-center gap-1">
            <Filter className="h-3.5 w-3.5 text-muted-foreground" />
            <select
              value={catFilter}
              onChange={e => setCatFilter(e.target.value)}
              className="h-8 rounded-md border border-border/60 bg-card text-xs px-2 text-foreground focus:outline-none focus:ring-1 focus:ring-primary"
            >
              {categories.map(c => (
                <option key={c} value={c}>{c === "all" ? "All categories" : c}</option>
              ))}
            </select>
          </div>
        )}
      </div>

      <p className="text-xs text-muted-foreground mb-3">
        Showing {filtered.length} of {items.length} items
        {filtered.length > 100 && <span className="ml-1 text-primary">(virtualized)</span>}
      </p>

      {/* ── Feed list ───────────────────────────────────────────────────────── */}
      {isLoading ? (
        <div className="text-center py-16 text-muted-foreground">
          <Radio className="h-8 w-8 mx-auto mb-3 animate-pulse text-primary" />
          Connecting to live feed…
        </div>
      ) : filtered.length === 0 ? (
        <div className="text-center py-16 text-muted-foreground">No items match your filters.</div>
      ) : (
        // Virtual scroll container — fixed height with overflow scroll
        <div
          ref={parentRef}
          className="overflow-auto rounded-lg border border-border/30"
          style={{ height: "72vh" }}
        >
          <div
            style={{
              height:   `${rowVirtualizer.getTotalSize()}px`,
              position: "relative",
            }}
          >
            {rowVirtualizer.getVirtualItems().map((virtualRow) => {
              const item = filtered[virtualRow.index];
              return (
                <div
                  key={virtualRow.key}
                  data-index={virtualRow.index}
                  ref={rowVirtualizer.measureElement}
                  style={{
                    position:  "absolute",
                    top:       0,
                    left:      0,
                    width:     "100%",
                    transform: `translateY(${virtualRow.start}px)`,
                  }}
                >
                  <Card
                    className={`border-l-4 border-r-0 border-t-0 border-b border-border/30 rounded-none backdrop-blur transition-all hover:bg-muted/20 ${SEV_COLOR[item.severity] || "border-l-border"}`}
                  >
                    <CardContent className="p-3 flex items-center gap-3">
                      <Badge className={`border text-[9px] font-bold uppercase w-14 justify-center shrink-0 ${SEV_BADGE[item.severity] || ""}`}>
                        {item.severity}
                      </Badge>
                      {/* Source attribution — links back to original source */}
                      <a
                        href={item.source_url ?? item.link}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-[10px] text-muted-foreground w-28 shrink-0 truncate hover:text-primary transition-colors"
                        title={`Source: ${item.source_name ?? "unknown"}`}
                      >
                        {item.source_name}
                      </a>
                      <a
                        href={item.link}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex-1 text-sm hover:text-primary hover:underline truncate"
                        title={item.title}
                      >
                        {item.title}
                      </a>
                      {item.category && (
                        <Badge variant="outline" className="text-[9px] shrink-0 hidden sm:flex">
                          {item.category}
                        </Badge>
                      )}
                      {/* ATT&CK technique badges */}
                      {item.mitre_techniques?.slice(0, 2).map(t => (
                        <Badge key={t} variant="outline" className="text-[9px] shrink-0 hidden lg:flex border-purple-500/40 text-purple-400">
                          {t}
                        </Badge>
                      ))}
                      <AISummaryDialog
                        summary={item.ai_summary}
                        generatedAt={(item as any).ai_summary_at}
                        model={(item as any).ai_model}
                        title="AI Summary"
                        triggerLabel="AI"
                        className="h-7 px-2 text-[11px] shrink-0"
                        itemId={item.id}
                        onGenerated={(s, m, g) => {
                          queryClient.setQueryData<ThreatItem[]>(FEED_QUERY_KEY, old =>
                            old ? old.map(i => i.id === item.id ? { ...i, ai_summary: s } : i) : old
                          );
                        }}
                      />
                      <button
                        onClick={() => toggleWatch(item)}
                        title={watchedIds.has(item.id) ? "Remove from watchlist" : "Add to watchlist"}
                        className={`shrink-0 transition-colors ${watchedIds.has(item.id) ? "text-primary" : "text-muted-foreground hover:text-primary"}`}
                      >
                        {watchedIds.has(item.id)
                          ? <BookmarkCheck className="h-3.5 w-3.5" />
                          : <Bookmark className="h-3.5 w-3.5" />}
                      </button>
                      <a
                        href={item.link}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="shrink-0 text-muted-foreground hover:text-primary transition-colors"
                      >
                        <ExternalLink className="h-3.5 w-3.5" />
                      </a>
                      <span className="text-[10px] text-muted-foreground shrink-0 flex items-center gap-1 w-16 justify-end">
                        <Calendar className="h-3 w-3" />{timeAgo(itemRecencyDate(item))}
                      </span>
                    </CardContent>
                  </Card>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}
