import { useEffect, useRef, useCallback } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { toast } from "@/components/ui/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { shouldShowFeedItem, sortByPriorityThenRecency } from "@/lib/feed-filters";

export interface ThreatItem {
  id: string;
  title: string;
  link: string;
  excerpt: string | null;
  severity: "critical" | "high" | "medium" | "low" | "info";
  published_at: string;
  fetched_at: string;
  source_name: string | null;
  source_url: string | null;
  category: string | null;
  iocs: Record<string, string[]> | null;
  confidence_score: number;
  severity_reasons: string[];
  mitre_techniques: string[];
  threat_actors: string[];
  malware_families: string[];
  ai_summary: string | null;
  cross_source_count: number;
}

interface UseRealtimeFeedOptions {
  orgId?: string;
  enabled?: boolean;
  onNewItem?: (item: ThreatItem) => void;
}

const FEED_QUERY_KEY = ["threat_items", "feed"] as const;

export function useRealtimeFeed({ orgId, enabled = true, onNewItem }: UseRealtimeFeedOptions = {}) {
  const queryClient = useQueryClient();
  const channelRef = useRef<ReturnType<typeof supabase.channel> | null>(null);

  const handleNewItem = useCallback((item: ThreatItem) => {
    queryClient.setQueryData<ThreatItem[]>(FEED_QUERY_KEY, (old) =>
      sortByPriorityThenRecency(old ? [item, ...old.filter(i => i.id !== item.id)] : [item]).slice(0, 500)
    );

    queryClient.invalidateQueries({ queryKey: ["threat_items", "counts"] });

    if (item.severity === "critical") {
      toast({
        title: "🚨 CRITICAL THREAT",
        description: item.title.slice(0, 120),
        variant: "destructive",
      });
    } else if (item.severity === "high" && item.confidence_score >= 75) {
      toast({
        title: "⚠️ High Severity Threat",
        description: item.title.slice(0, 120),
      });
    }

    onNewItem?.(item);
  }, [queryClient, onNewItem]);

  useEffect(() => {
    if (!enabled) return;

    const channelName = `threat_items:${orgId ?? "global"}`;

    const channel = supabase
      .channel(channelName)
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "threat_items",
        },
        (payload) => {
          const item = payload.new as ThreatItem;
          if (!shouldShowFeedItem(item)) return;
          handleNewItem(item);
        }
      )
      .on(
        "postgres_changes",
        {
          event: "UPDATE",
          schema: "public",
          table: "threat_items",
        },
        (payload) => {
          const updated = payload.new as ThreatItem;
          queryClient.setQueryData<ThreatItem[]>(FEED_QUERY_KEY, (old) => {
            if (!old) return old;
            const next = old.map(item => item.id === updated.id ? { ...item, ...updated } : item);
            return sortByPriorityThenRecency(next);
          });
        }
      )
      .subscribe((status) => {
        if (status === "SUBSCRIBED") {
          console.log(`[Realtime] Connected to ${channelName}`);
        }
      });

    channelRef.current = channel;

    return () => {
      supabase.removeChannel(channel);
      channelRef.current = null;
    };
  }, [orgId, enabled, handleNewItem, queryClient]);

  return {
    isConnected: channelRef.current !== null,
  };
}
